TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs, unsigned long attr_count) {
    TEE_Result result = TEE_ERROR_GENERIC;
    struct crypto_session *session = get_current_session();
    struct crypto_object *crypto_obj = NULL;
    struct utee_attribute *attrs = NULL;

    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    crypto_obj = get_crypto_object_by_id(obj);
    if (!crypto_obj || !crypto_obj->is_transient || crypto_obj->is_initialized) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    attrs = calloc(attr_count, sizeof(*attrs));
    if (!attrs) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    if (copy_from_user(attrs, usr_attrs, attr_count * sizeof(*usr_attrs)) != 0) {
        result = TEE_ERROR_BAD_PARAMETERS;
        goto cleanup;
    }

    result = validate_attributes_against_object(attrs, attr_count, crypto_obj);
    if (result != TEE_SUCCESS) {
        goto cleanup;
    }

    result = apply_attributes_to_object(crypto_obj, attrs, attr_count);
    if (result != TEE_SUCCESS) {
        goto cleanup;
    }

    crypto_obj->is_initialized = 1;

cleanup:
    free(attrs);
    return result;
}

TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs,
                                  unsigned long attr_count)
{
    TEE_Result res = TEE_ERROR_GENERIC;
    struct crypto_session *sess = get_current_session();
    struct crypto_object *c_obj;

    if (!sess || obj >= MAX_CRYPTO_OBJECTS)
        return TEE_ERROR_BAD_PARAMETERS;

    c_obj = &sess->objects[obj];
    if (!c_obj || c_obj->type != TEE_TYPE_TRANIENT_CRYPTO_OBJECT || c_obj->state != TEE_HANDLE_STATE_CLOSED)
        return TEE_ERROR_BAD_PARAMETERS;

    c_obj->attributes = calloc(attr_count, sizeof(struct crypto_attribute));
    if (!c_obj->attributes)
        return TEE_ERROR_OUT_OF_MEMORY;

    for (unsigned long i = 0; i < attr_count; i++) {
        c_obj->attributes[i] = *usr_attrs[i];
        if (validate_attribute(c_obj->type, &c_obj->attributes[i]) != TEE_SUCCESS) {
            res = TEE_ERROR_BAD_PARAMETERS;
            goto cleanup;
        }
    }

    if (initialize_crypto_object(c_obj) != TEE_SUCCESS)
        goto cleanup;

    c_obj->state = TEE_HANDLE_STATE_ACTIVE;
    res = TEE_SUCCESS;

cleanup:
    if (res != TEE_SUCCESS)
        free(c_obj->attributes);
    return res;
}

TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs,
                                  unsigned long attr_count)
{
    TEE_Result res = TEE_ERROR_BAD_PARAMETERS;
    struct crypto_session *sess = get_current_session();
    struct crypto_object *crypto_obj = get_crypto_object_by_id(obj);

    if (!sess || !crypto_obj || !usr_attrs || !attr_count)
        return TEE_ERROR_BAD_PARAMETERS;

    if (crypto_obj->type != TEE_TYPE_TRANSIENT_MEMORY ||
        crypto_obj->state != TEE_OBJECT_STATE_UNINITIALIZED) {
        return TEE_ERROR_BAD_STATE;
    }

    crypto_obj->attributes = calloc(attr_count, sizeof(struct tee_attribute));
    if (!crypto_obj->attributes)
        return TEE_ERROR_OUT_OF_MEMORY;

    for (unsigned long i = 0; i < attr_count; i++) {
        struct utee_attribute *src = &usr_attrs[i];
        struct tee_attribute *dst = &crypto_obj->attributes[i];

        dst->attr = src->attr;
        dst->value = src->value;
        dst->size = src->size;
    }

    res = validate_attributes(crypto_obj, attr_count);
    if (res != TEE_SUCCESS)
        goto cleanup;

    res = initialize_crypto_object(crypto_obj);
    if (res != TEE_SUCCESS)
        goto cleanup;

    crypto_obj->state = TEE_OBJECT_STATE_INITIALIZED;
    return TEE_SUCCESS;

cleanup:
    free(crypto_obj->attributes);
    crypto_obj->attributes = NULL;
    return res;
}

TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs, unsigned long attr_count) {
    TEE_Result res = TEE_ERROR_GENERIC;
    struct tee_session *session = tee_get_current_session();
    struct tee_object *object;

    if (!session)
        return TEE_ERROR_BAD_STATE;

    object = tee_get_object_by_id(session, obj);
    if (!object || !object->is_transient || object->is_initialized)
        return TEE_ERROR_BAD_PARAMETERS;

    object->attributes = malloc(attr_count * sizeof(struct tee_attribute));
    if (!object->attributes)
        return TEE_ERROR_OUT_OF_MEMORY;

    for (unsigned long i = 0; i < attr_count; i++) {
        object->attributes[i] = *usr_attrs[i].attribute;
        if (!tee_validate_attribute(object, &object->attributes[i])) {
            res = TEE_ERROR_BAD_PARAMETERS;
            goto cleanup;
        }
    }

    object->attr_count = attr_count;
    object->is_initialized = 1;
    res = TEE_SUCCESS;

cleanup:
    if (res != TEE_SUCCESS)
        free(object->attributes);

    return res;
}

TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs, unsigned long attr_count) {
    TEE_Result res = TEE_SUCCESS;
    struct tee_internal_session *session = tee_get_current_session();
    struct tee_object *obj_desc = tee_get_object_by_id(obj);

    if (!obj_desc || !obj_desc->is_transient || obj_desc->is_initialized) {
        return TEE_ERROR_BAD_STATE;
    }

    obj_desc->attributes = calloc(attr_count, sizeof(struct tee_attribute));
    if (!obj_desc->attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    for (unsigned long i = 0; i < attr_count; i++) {
        res = tee_copy_from_user(&obj_desc->attributes[i], &usr_attrs[i], sizeof(struct utee_attribute));
        if (res != TEE_SUCCESS) {
            free(obj_desc->attributes);
            return res;
        }
    }

    res = validate_attributes_against_type(obj_desc->type, obj_desc->attributes, attr_count);
    if (res != TEE_SUCCESS) {
        free(obj_desc->attributes);
        return res;
    }

    obj_desc->is_initialized = 1;

    return TEE_SUCCESS;
}
